/** Server xəta kodu → yazı */
export function tgError(e, t) {
  const E = t.err
  if (e && e.status === 429) return E.rate
  const c = e && e.code
  const map = {
    consent_required: E.consent, full: E.full, too_many: E.tooMany, invalid_token: E.token, taken: E.taken, not_mine: E.notMine,
    not_ramadan: E.notRamadan, bad_title: E.title, bad_date: E.date, bad_day: E.date, bad_range: E.range, self: E.self, ended: E.ended,
    bad_name: E.name, owner_only: E.notMine, teacher_only: E.notMine, not_found: E.token,
  }
  if (c && map[c]) return map[c]
  if (e instanceof TypeError) return E.net
  return E.unknown
}
